import { TreeSelect, type TreeSelectChangeDetail } from '@absoluteui/components/tree-select';

const host = document.createElement('div');
document.body.append(host);
const field = TreeSelect.create(host, {
  label: 'Department',
  name: 'department',
  required: true,
  placeholder: 'Choose a department',
  nodes: [
    { id: 'eng', label: 'Engineering', children: [
      { id: 'eng-platform', label: 'Platform' },
      { id: 'eng-web', label: 'Web' },
    ] },
    { id: 'ops', label: 'Operations', children: [{ id: 'ops-facilities', label: 'Facilities' }] },
  ],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<TreeSelectChangeDetail>).detail;
  host.dataset.department = value[0] ?? '';
});
field.reportValidity();

import { TreeSelect, type TreeNode } from '@absoluteui/components/tree-select';

const host = document.createElement('div');
document.body.append(host);
TreeSelect.create(host, {
  label: 'Locations',
  mode: 'multiple',
  name: 'locations',
  value: ['berlin'],
  valueLabels: { berlin: 'Berlin' },
  nodes: [
    { id: 'emea', label: 'Europe', hasChildren: true },
    { id: 'apac', label: 'Asia Pacific', hasChildren: true },
  ],
  loadChildren: async (node, { signal }) => {
    const res = await fetch(`/api/locations?parent=${encodeURIComponent(node.id)}`, { signal });
    return (await res.json()) as TreeNode[];
  },
});
